From 3999b227fc2255371b786ccec62cba3f47af37f5 Mon Sep 17 00:00:00 2001
From: xiaotiansf <xiaotianshimail@gmail.com>
Date: Wed, 3 Apr 2019 10:53:18 -0700
Subject: [PATCH] Fix oss-fuzzer 14035. Reset all B-frame's reference's
 references when IDR is lost to prevent temporal prediction from trying to
 access lost references.

---
 codec/decoder/core/src/manage_dec_ref.cpp | 8 ++++++++
 1 file changed, 8 insertions(+)

diff --git a/codec/decoder/core/src/manage_dec_ref.cpp b/codec/decoder/core/src/manage_dec_ref.cpp
index 56ee943..834dd2b 100644
--- a/codec/decoder/core/src/manage_dec_ref.cpp
+++ b/codec/decoder/core/src/manage_dec_ref.cpp
@@ -126,6 +126,14 @@ static int32_t WelsCheckAndRecoverForFutureDecoding (PWelsDecoderContext pCtx) {
         pRef->bIsComplete = false; // Set complete flag to false for lost IDR ref picture
         pRef->iSpsId = pCtx->pSps->iSpsId;
         pRef->iPpsId = pCtx->pPps->iPpsId;
+        if (pCtx->eSliceType == B_SLICE) {
+          //reset reference's references when IDR is lost
+          for (int32_t list = LIST_0; list < LIST_A; ++list) {
+            for (int32_t i = 0; i < 17; ++i) {
+              pRef->pRefPic[list][i] = NULL;
+            }
+          }
+        }
         pCtx->iErrorCode |= dsDataErrorConcealed;
         bool bCopyPrevious = ((ERROR_CON_FRAME_COPY_CROSS_IDR == pCtx->pParam->eEcActiveIdc)
                               || (ERROR_CON_SLICE_COPY_CROSS_IDR == pCtx->pParam->eEcActiveIdc)
